import numpy as npimport matplotlib.pyplot as pltimport timestart = time.time()def mandelbrot_point(c, max_iter=100):    z = 0 + 0j  # z_0        for n in range(max_iter):        z = z*z + c                  if abs(z) > 2:            return n         return max_iter  x_min, x_max = -2, 1      y_min, y_max = -1.5, 1.5 width, height = 1024, 1024x_values = np.linspace(x_min, x_max, width)y_values = np.linspace(y_min, y_max, height)C = np.zeros((height, width), dtype=np.complex128)for i in range(height):      # i = row index (y-axis)    for j in range(width):   # j = column index (x-axis)        # For each point, c = x + i*y        C[i, j] = x_values[j] + 1j * y_values[i]iterations = np.zeros((height, width), dtype=int)for i in range(height):    for j in range(width):        iterations[i, j] = mandelbrot_point(C[i, j])                elapsed = time.time() - startprint(f"Computation took {elapsed:.3f} seconds")    plt.figure(figsize=(10, 8))plt.imshow(iterations, extent=[x_min, x_max, y_min, y_max],            cmap='hot', origin='lower')plt.colorbar(label='Iterations until escape')plt.title('Mandelbrot Set')plt.xlabel('Re(c)')plt.ylabel('Im(c)')plt.show()